"""Independent reconstruction from inertial pressure-branch coordinates, tensor blocks and controls."""
from collections import defaultdict
from hashlib import sha256
import json,sys
from pathlib import Path
import numpy as np
from scipy.linalg import expm
from scipy.stats import t
from endpoint import direct

base=Path(sys.argv[1]); dst=Path(sys.argv[2]); load=lambda p:json.loads(p.read_bytes()); sha=lambda p:sha256(p.read_bytes()).hexdigest()
def close(a,b): np.testing.assert_allclose(a,b,rtol=2e-9,atol=4e-8)
def guard(p):
    o,c,l,d,i=[load(p/n) for n in ('outcome.json','child-outcome.json','limit-validation.json','duration-validation.json','invocation.json')]
    assert c['guardReason'] is None and o['exitCode']==o['stderrBytes']==c['exitCode']==0 and o['childOutcome']==c
    assert l['verified'] and int(l['actual']['memory.max'])==i['memoryMax'] and int(l['actual']['memory.swap.max'])==0 and i['pool']=='s11c'
    assert d['verified'] and d['actual']['RuntimeMaxUSec']=='infinity' and d['inactivityDeadlineSeconds'] is None and d['wallDeadlineSeconds'] is None

def stats(x):
    x=np.asarray(x); a=x.mean();rad=x.std(ddof=1)/np.sqrt(len(x))*t.ppf(.975,len(x)-1)
    return {'per_preparation':x.tolist(),'mean':float(a),'t95':[float(a-rad),float(a+rad)]}

def ratios(x,y):
    # Intersect a family of t confidence intervals with zero for candidate r = mean(late)/mean(initial).
    x=np.asarray(x); y=np.asarray(y);mx=x.mean();my=y.mean();cov=np.cov(x,y,ddof=1);q=t.ppf(.975,len(x)-1)**2/len(x)
    a=mx**2-q*cov[0,0];b=mx*my-q*cov[0,1];c=my**2-q*cov[1,1];disc=b*b-a*c
    if a<=0 or disc<0: return {'mean_ratio':float(my/mx),'bounded_interval':None,'a':a,'discriminant':disc}
    return {'mean_ratio':float(my/mx),'bounded_interval':[(b-np.sqrt(disc))/a,(b+np.sqrt(disc))/a]}

def measured_state(s,reading,axis):
    x,box,v=[np.array(s[k]) for k in ('pos','box','vel')]; en,stress=direct(x,v,box)
    stored=np.array(reading['stress_tensile']); close(en/len(x),reading['potential_per_site']); close(stress,stored)
    close(np.sum(axis*stress),reading['shear']);close(-np.trace(stress)/4,reading['pressure']);close(np.linalg.det(box),reading['volume']);close(len(x)/np.linalg.det(box),reading['density']);close(np.mean(v**2),reading['temperature'])
    return max(abs(stress-stored).flatten())

def check_reading(value,axis):
    s=np.array(value['stress_tensile']);close(s,s.T);close(-np.trace(s)/4,value['pressure']);close(np.sum(axis*s),value['shear'])
    assert np.isfinite(s).all() and value['density']>0 and value['temperature']>0

def post_waves(state,h):
    frac=np.array(state['pos'])@np.linalg.inv(state['box']); arg=2*np.pi*np.array(h)@frac.T
    return (np.cos(arg).mean(axis=1)**2+np.sin(arg).mean(axis=1)**2).tolist()

def window(b,field):return np.average([t['mean'][field] for t in b[-4:]],weights=[t['steps'] for t in b[-4:]])

from itertools import product

def waves(state,known=None):
    cell=np.array(state['box']);fraction=np.array(state['pos'])@np.linalg.inv(cell);r=12.*np.linalg.norm(cell,axis=1)/(2*np.pi)
    extent=np.floor(r).astype(int); idx=np.array([h for h in product(*(range(-k,k+1) for k in extent)) if h>(0,0,0,0)])
    true=2*np.pi*np.linalg.solve(cell,idx.T).T; idx=idx[np.einsum('ij,ij->i',true,true)<=144.]
    def powers(h):
        z=2*np.pi*h@fraction.T
        return np.cos(z).mean(axis=1)**2 + np.sin(z).mean(axis=1)**2
    vals=np.concatenate([powers(x) for x in np.array_split(idx,max(1,len(idx)//128))]);chosen=[]
    for item in np.argsort(-vals):
        sub=idx[chosen+[item]]
        if np.linalg.matrix_rank(sub)==len(chosen)+1: chosen.append(item)
        if len(chosen)==4: break
    h=idx[chosen];p=vals[chosen];res={'h':h.tolist(),'power':p.tolist(),'peak':float(p[0])}
    if known is not None:res['fixed']=powers(np.array(known)).tolist()
    return res

from scipy.sparse.csgraph import connected_components

def bond(state):
    cell=np.array(state['box']);points=np.array(state['pos'])@np.linalg.inv(cell);i,j=np.triu_indices(len(points),1);d=points[j]-points[i];d-=np.rint(d)
    ext=np.floor(.5+1.31*np.linalg.norm(np.linalg.inv(cell),axis=0)).astype(int);dist=np.full(len(i),1e100)
    for offset in product(*(range(-k,k+1) for k in ext)):
        phys=(d+offset)@cell;dist=np.minimum(dist,np.einsum('ij,ij->i',phys,phys))
    return dist<1.15**2,dist<1.30**2

def move(first,now):
    init=np.array(first['box']);new=np.array(now['box']);dr=np.array(now['pos'])@np.linalg.inv(new)@init-np.array(first['pos']);dr-=dr.mean(axis=0);return np.sqrt(np.einsum('ij,ij->',dr,dr)/len(dr))

def over(blocks):
    weights=[b['steps'] for b in blocks]
    values={q:float(np.average([b['mean'][q] for b in blocks],weights=weights)) for q in ('pressure','temperature','density')}
    tensor=np.average([b['mean']['stress_tensile'] for b in blocks],axis=0,weights=weights)
    values['normal_pressure_w']=float(-tensor[3,3])
    values['mean_tangential_pressure_xyz']=float(-np.trace(tensor[:3,:3])/3)
    close((values['normal_pressure_w']+3*values['mean_tangential_pressure_xyz'])/4,values['pressure'])
    return values

import numpy as np
import itertools
def score(state):
    x=np.array(state['pos']); b=np.array(state['box']); f=((x@np.linalg.inv(b))%1.);delta=f[None,:,:]-f[:,None,:];delta-=np.rint(delta)
    ext=np.floor(.5+1.3*np.linalg.norm(np.linalg.inv(b),axis=0)+1e-12).astype(int);bonds=[[] for _ in f]
    for shift in itertools.product(*(range(-m,m+1) for m in ext)):
        displacement=(delta+shift)@b;rr=np.linalg.norm(displacement,axis=2);i,j=np.nonzero((rr>1.e-10)&(rr<1.30))
        for s,row in zip(i,displacement[i,j]/rr[i,j,None]):bonds[s].append(row)
    means=[]
    for vs in bonds:
        if len(vs)<2:
            means.append(float('nan'))
            continue
        vs=np.array(vs);i,j=np.triu_indices(len(vs),1)
        cos=np.einsum('ij,ij->i',vs[i],vs[j]);theta=np.arccos(np.clip(cos,-1.,1.));s=np.sin(theta);val=np.ones_like(theta);np.divide(np.sin(7*theta),7*s,out=val,where=s>1.e-8);means.append(val.mean())
    return np.array(means),f[:,3]

